import { FormEvent, useState } from "react";
import { executeDynamicMutation, getDynamicLookup, LookupRow } from "../../api/lookups";
import { AutoDismissAlert } from "../../components/ui/AutoDismissAlert";
import { Input } from "../../components/ui/Input";
import { LookupField } from "../../components/ui/LookupField";
import { useAuth } from "../../state/AuthContext";
import { IdCard } from "lucide-react";
import type { LucideIcon } from "lucide-react";

const Account_AC_CODE_Serach = "Account_AC_CODE_Serach";

//   P_VAL1S1 : EXPENSE_CODE  (blank on insert -> autogenerated in Oracle)
//   P_VAL1S2 : COMPANY_CODE
//   P_VAL1S3 : EXPENSE_NAME
//   P_VAL1S4 : AC_CODE
//   P_VAL1S5 : USER_ID
const PURCHASE_SALE_MSE_EXPENSES = "PURCHASE_SALE_MSE_EXPENSES";

export type TExpenseMaster = {
  expense_code?: string;
  expense_name?: string;
  ac_code?: string;
  ac_name?: string;
  user_id?: string;
  user_dt?: string;
  date1?: string | null;
};

type FormMode = "add" | "edit" | "view";

type Props = {
  mode: FormMode;
  existingData?: Partial<TExpenseMaster>;
  onClose: (shouldRefetch?: boolean) => void;
  onSavingChange?: (saving: boolean) => void;
};

const EMPTY: TExpenseMaster = {
  expense_code: "",
  expense_name: "",
  ac_code: "",
  ac_name: "",
  user_id: "",
  user_dt: "",
};

const accountColumns = [
  { field: "ac_code", header: "A/C Code" },
  { field: "ac_name", header: "A/C Name" },
];

/* ─────────────────────────────────────────────────────────────
   SectionPanel — EXACT Freight structure (from WMS)
   ───────────────────────────────────────────────────────────── */
function SectionPanel({
  title,
  icon: Icon,
  children,
}: {
  title: string;
  icon: LucideIcon;
  children: React.ReactNode;
}) {
  return (
    <section className="freight-panel overflow-hidden rounded-md border bg-background shadow-sm">
      <div className="freight-panel-title flex items-center justify-between gap-2 border-b bg-muted/35 px-3 py-2">
        <div className="flex min-w-0 items-center gap-2">
          <span className="freight-section-icon">
            <Icon size={16} />
          </span>
          <div className="min-w-0">
            <h3 className="m-0 truncate text-[11px] font-semibold text-foreground">{title}</h3>
          </div>
        </div>
      </div>
      <div className="freight-panel-body p-3">{children}</div>
    </section>
  );
}

/* ─────────────────────────────────────────────────────────────
   Field — matches WmsMasterForm / Freight label styling
   ───────────────────────────────────────────────────────────── */
function Field({
  label,
  required,
  children,
  className,
}: {
  label: string;
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <label className={`freight-field-label group flex flex-col gap-0.5 ${className ?? ""}`}>
      <span className="text-[11px] font-medium text-muted-foreground group-focus-within:text-primary transition-colors">
        {label}
        {required && <strong className="text-destructive ml-0.5 font-bold"> *</strong>}
      </span>
      {children}
    </label>
  );
}

export function AddExpenseMasterForm({ mode, existingData, onClose, onSavingChange }: Props) {
  const { user } = useAuth();
  const readonly = mode === "view";
  const isEdit = mode === "edit";
  const companyCode = user?.company_code ?? "";

  const [form, setForm] = useState<TExpenseMaster>(() => ({ ...EMPTY, ...existingData }));
  const [errors, setErrors] = useState<Partial<Record<keyof TExpenseMaster, string>>>({});
  const [apiError, setApiError] = useState("");

  const setField = (field: keyof TExpenseMaster, value: string) =>
    setForm((prev) => ({ ...prev, [field]: value }));

  const validate = (): boolean => {
    const next: Partial<Record<keyof TExpenseMaster, string>> = {};
    if (!form.expense_name?.trim()) next.expense_name = "Expense Name is required";
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (readonly) return;
    if (!validate()) return;

    onSavingChange?.(true);
    setApiError("");
    try {
      await executeDynamicMutation({
        parameter: PURCHASE_SALE_MSE_EXPENSES,
        loginid: user?.loginid ?? "ADMIN",
        val1s1: isEdit ? form.expense_code ?? "" : "",
        val1s2: companyCode,
        val1s3: form.expense_name?.trim() ?? "",
        val1s4: form.ac_code ?? "",
        val1s5: user?.loginid ?? "ADMIN",
      });

      onClose(true);
    } catch (error) {
      setApiError(error instanceof Error ? error.message : "Unable to save expense master record");
    } finally {
      onSavingChange?.(false);
    }
  };

  return (
    <form className="grid content-start gap-4" id="expense-master-form" onSubmit={handleSubmit}>
      <AutoDismissAlert
        notice={apiError ? { type: "error", message: apiError } : null}
        onClose={() => setApiError("")}
      />

      <SectionPanel title="Basic Information" icon={IdCard}>
        <div className="grid grid-cols-1 gap-3 md:grid-cols-2">
          
          <Field label="Expense Code">
            <Input disabled value={form.expense_code || "Autogenerated"} />
          </Field>

          <Field label="Expense Name" required>
            <Input
              disabled={readonly}
              value={form.expense_name ?? ""}
              onChange={(e) => setField("expense_name", e.target.value)}
              placeholder="e.g. Office Supplies"
              className={errors.expense_name ? "border-destructive focus-visible:ring-destructive" : ""}
            />
            {errors.expense_name && <span className="mt-0.5 text-[10px] font-medium text-destructive">{errors.expense_name}</span>}
          </Field>

          <Field label="A/C Code" className="md:col-span-2">
            <LookupField
              label=""
              value={form.ac_code ?? ""}
              columns={accountColumns}
              valueField="ac_code"
              displayFields={["ac_code", "ac_name"]}
              disabled={readonly}
              loadOptions={() =>
                getDynamicLookup({
                  parameter: Account_AC_CODE_Serach,
                  code1: companyCode,
                  code2: "",
                  code3: "",
                  code4: "",
                  number1: 0,
                  number2: 0,
                  number3: 0,
                  number4: 0,
                  date1: null,
                  date2: null,
                  date3: null,
                  date4: null,
                })
              }
              onChange={(value, row) => {
                setField("ac_code", value);
                if (row) setField("ac_name", String(row.ac_name ?? ""));
              }}
              compact
            />
          </Field>

        </div>
      </SectionPanel>
    </form>
  );
}